const j = $input.first().json;
let state = {};
try { state = j.stateRaw ? JSON.parse(j.stateRaw) : {}; } catch (e) {}
const step = state.step || 'IDLE';
const cb = j.callbackData || '';

const LABELS = {
  mama_entrega_dinero: 'Mama me entrego dinero',
  erick_gasta_para_mama: 'Yo gaste para mama',
  erick_entrega_dinero: 'Yo le entregue dinero',
  mama_devuelve: 'Mama me devolvio dinero',
  erick_devuelve: 'Yo le devolvi dinero'
};
function kb(rows){return {rows: rows.map(r => ({row:{buttons: r.map(b => ({button:{text:b.t, additionalFields:{callback_data:b.d}}}))}}))};}
const K_EVENT = kb(Object.keys(LABELS).map(k => [{t: LABELS[k], d: 'evt:'+k}]));
const K_SCOPE = kb([[{t:'El tipo',d:'corr:scope:tipo'},{t:'El monto/descripcion',d:'corr:scope:md'}],[{t:'La fecha',d:'corr:scope:fecha'},{t:'Todo',d:'corr:scope:todo'}],[{t:'Cancelar',d:'cancel'}]]);
const K_DATE  = kb([[{t:'Hoy',d:'date:hoy'},{t:'Ayer',d:'date:ayer'}],[{t:'Otra fecha',d:'date:otra'},{t:'Cancelar',d:'cancel'}]]);
const K_CONF  = kb([[{t:'CONFIRMAR',d:'confirm'},{t:'CANCELAR',d:'cancel'}]]);

function limaISO(off){
  const p = new Intl.DateTimeFormat('en-CA',{timeZone:'America/Lima',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
  const d = new Date(p + 'T00:00:00Z'); d.setUTCDate(d.getUTCDate() + (off||0));
  return d.toISOString().slice(0,10);
}
function out(o){ return [{ json: Object.assign({ chatId: j.chatId, leg:0, replyText:'', n8nKeyboard:null, redisAction:'keep', stateNext:null, apiBody:null, apiTargetId:null }, o) }]; }

if (j.isCallback && cb === 'cancel')
  return out({ leg:0, redisAction:'del', replyText:'Correccion cancelada.' });

if (step === 'PROCESSING_CORRECTION')
  return out({ leg:4 });

// fresh /corregir, or forwarded from A after 'Cancelar y corregir' -> fetch the list (leg 2)
if (j.forceCorrection || step === 'IDLE' || (!j.isCallback && j.text === '/corregir'))
  return out({ leg:2 });

if (step === 'WAITING_CORRECTION_SELECTION') {
  if (j.isCallback && cb.indexOf('corr:pick:') === 0) {
    const idx = parseInt(cb.split(':')[2], 10);
    const target = (state.list || [])[idx];
    if (!target) return out({ leg:0, redisAction:'del', replyText:'Seleccion invalida. Envia /corregir de nuevo.' });
    return out({ leg:1, redisAction:'set',
      stateNext: Object.assign({}, state, { step:'WAITING_CORRECTION_SCOPE', target }),
      replyText: 'Vas a corregir:\n' + target.event_date + ' - S/ ' + target.amount + ' - ' + target.description + '\n\nQue deseas corregir?',
      n8nKeyboard: K_SCOPE });
  }
  return out({ leg:0, replyText:'Elige un registro de la lista, o envia /corregir de nuevo.' });
}

if (step === 'WAITING_CORRECTION_SCOPE' && j.isCallback && cb.indexOf('corr:scope:') === 0) {
  const scope = cb.split(':')[2];
  const base = Object.assign({}, state, { scope });
  if (scope === 'tipo' || scope === 'todo')
    return out({ leg:1, redisAction:'set', stateNext: Object.assign({}, base, { step:'WAITING_CORRECTION_EVENT_TYPE' }),
      replyText:'Nuevo tipo de operacion:', n8nKeyboard: K_EVENT });
  if (scope === 'md')
    return out({ leg:0, redisAction:'set', stateNext: Object.assign({}, base, { step:'WAITING_CORRECTION_TEXT' }),
      replyText:'Escribe el nuevo monto y descripcion. Ej:  S/ 40.00 taxi' });
  if (scope === 'fecha')
    return out({ leg:1, redisAction:'set', stateNext: Object.assign({}, base, { step:'WAITING_CORRECTION_DATE' }),
      replyText:'Nueva fecha:', n8nKeyboard: K_DATE });
}

function toConfirm(st){
  const key = 'telegram:' + j.chatId + ':update:' + j.updateId;
  const t = st.target || {};
  const evtAfter  = st.new_event_type || t.event_type;
  const dateAfter = st.new_event_date || t.event_date;
  const before = (LABELS[t.event_type] || t.event_type) + ' - S/ ' + t.amount + ' - ' + t.description + ' - ' + t.event_date;
  let after;
  if (st.new_raw_text) {
    // amount + description are only known after the API parses the text, so do
    // NOT show the old amount as if it were final.
    after = (LABELS[evtAfter] || evtAfter) + ' - [monto y descripcion a interpretar de: "' + st.new_raw_text + '"] - ' + dateAfter;
  } else {
    after = (LABELS[evtAfter] || evtAfter) + ' - S/ ' + t.amount + ' - ' + t.description + ' - ' + dateAfter;
  }
  const txt = 'Revisa la correccion:\n\nAntes:\n' + before + '\n\nDespues:\n' + after + '\n\nConfirmas?';
  return out({ leg:1, redisAction:'set',
    stateNext: Object.assign({}, st, { step:'WAITING_CORRECTION_CONFIRMATION', pending_idempotency_key: st.pending_idempotency_key || key }),
    replyText: txt, n8nKeyboard: K_CONF });
}

if (step === 'WAITING_CORRECTION_EVENT_TYPE' && j.isCallback && cb.indexOf('evt:') === 0) {
  const st = Object.assign({}, state, { new_event_type: cb.slice(4) });
  if (st.scope === 'todo')
    return out({ leg:0, redisAction:'set', stateNext: Object.assign({}, st, { step:'WAITING_CORRECTION_TEXT' }),
      replyText:'Escribe el nuevo monto y descripcion. Ej:  S/ 40.00 taxi' });
  return toConfirm(st);
}

if (step === 'WAITING_CORRECTION_TEXT' && !j.isCallback && j.text) {
  const st = Object.assign({}, state, { new_raw_text: j.text });
  if (st.scope === 'todo')
    return out({ leg:1, redisAction:'set', stateNext: Object.assign({}, st, { step:'WAITING_CORRECTION_DATE' }),
      replyText:'Nueva fecha:', n8nKeyboard: K_DATE });
  return toConfirm(st);
}

if (step === 'WAITING_CORRECTION_DATE') {
  let dateISO = null;
  if (j.isCallback && cb === 'date:hoy') dateISO = limaISO(0);
  else if (j.isCallback && cb === 'date:ayer') dateISO = limaISO(-1);
  else if (j.isCallback && cb === 'date:otra')
    return out({ leg:0, redisAction:'set', stateNext: Object.assign({}, state, { step:'WAITING_CORRECTION_DATE_MANUAL' }),
      replyText:'Escribe la fecha como AAAA-MM-DD.' });
  else return out({ leg:1, replyText:'Elige una fecha.', n8nKeyboard: K_DATE });
  return toConfirm(Object.assign({}, state, { new_event_date: dateISO }));
}

if (step === 'WAITING_CORRECTION_DATE_MANUAL' && !j.isCallback && /^\d{4}-\d{2}-\d{2}$/.test(j.text))
  return toConfirm(Object.assign({}, state, { new_event_date: j.text }));

if (step === 'WAITING_CORRECTION_CONFIRMATION' && j.isCallback && (cb === 'confirm' || cb === 'retry')) {
  const st = state;
  const key = st.pending_idempotency_key || ('telegram:' + j.chatId + ':update:' + j.updateId);
  const body = { telegram_user_id: String(j.fromId), idempotency_key: key };
  if (st.new_event_type) body.event_type = st.new_event_type;
  if (st.new_event_date) body.event_date = st.new_event_date;
  if (st.new_raw_text) body.raw_text = st.new_raw_text;
  return out({ leg:3, redisAction:'set',
    stateNext: Object.assign({}, st, { step:'PROCESSING_CORRECTION', pending_idempotency_key: key }),
    apiTargetId: (st.target || {}).id, apiBody: body });
}

return out({ leg:0, redisAction:'del', replyText:'No entendi. Envia /corregir para empezar de nuevo.' });

const r = $input.first().json;
const body = r.body || r;
const chatId = $('Correccion SM').item.json.chatId;
const rows = (body.transactions || []).map((t) => ({ id: t.id, event_type: t.event_type, amount: t.amount, description: t.description, event_date: t.event_date }));

if (rows.length === 0) {
  return [{ json: { chatId, leg:0, redisAction:'del', replyText:'No tienes registros para corregir.', n8nKeyboard:null, stateNext:null } }];
}

const btns = rows.map((t, i) => ([{ text: (i+1) + '. ' + t.event_date + ' - S/ ' + t.amount + ' - ' + t.description, callback_data: 'corr:pick:' + i }]));
btns.push([{ text: 'Cancelar', callback_data: 'cancel' }]);
const n8nKeyboard = { rows: btns.map(row => ({ row: { buttons: row.map(b => ({ button: { text: b.text, additionalFields: { callback_data: b.callback_data } } })) } })) };

return [{ json: {
  chatId, leg:1, redisAction:'set',
  stateNext: { step:'WAITING_CORRECTION_SELECTION', list: rows },
  replyText: 'Estos son tus ultimos registros. Cual deseas corregir?',
  n8nKeyboard
}}];

const r = $input.first().json;
const status = r.statusCode || (r.body ? 200 : 0);
const body = r.body || r;
const chatId = $('Correccion SM').item.json.chatId;
const fromId = String($('Inicio (desde A)').item.json.fromId);
const smState = $('Correccion SM').item.json.stateNext || {};

// TODO (Step 8): map each telegram_user_id -> the OTHER person's chat id.
const OTHER = {};   // e.g. { "111": "222", "222": "111" }

if (status >= 200 && status < 300) {
  const c = body.correction || {};
  const b = body.balance || {};
  const dir = b.direction === 'erick_owes_mama' ? 'Erick le debe a Mama'
           : b.direction === 'mama_owes_erick' ? 'Mama le debe a Erick'
           : 'No hay deuda pendiente';
  return [{ json: {
    ok: true, chatId,
    replyText: 'Correccion aplicada\n\n' + c.description + '  -  S/ ' + c.amount + '\n\nSaldo actualizado:\n' + dir + ': S/ ' + b.balance,
    notifyChatId: OTHER[fromId] || null,
    notifyText: 'La otra persona corrigio un registro. El saldo se actualizo.',
    revertState: null
  }}];
}

const code = (body.error && body.error.code) || 'INTERNAL_ERROR';
const MSG = {
  CORRECTION_NOT_ALLOWED: 'Solo puedes corregir tus propios registros.',
  TRANSACTION_NOT_FOUND: 'No encontre ese registro.',
  TRANSACTION_NOT_ACTIVE: 'Ese registro ya fue corregido antes. Envia /corregir para ver el actual.',
  PARSER_FAILED: 'No entendi el monto. Escribe algo como:  S/ 40.00 taxi',
  INVALID_AMOUNT: 'El monto no es valido (positivo, maximo 2 decimales).',
  INVALID_EVENT_DATE: 'La fecha no es valida o esta en el futuro.'
};
return [{ json: {
  ok: false, chatId, notifyChatId: null,
  replyText: MSG[code] || 'Hubo un problema. Intenta de nuevo en un momento.',
  revertState: Object.assign({}, smState, { step: 'WAITING_CORRECTION_CONFIRMATION' })
}}];
